import {modules, exercises} from './curriculum.js';
import {evaluate, escapeHTML as esc, frameDocument, freshRecord, restoreState, initialState, resetExercise} from './engine.js';
const $=id=>document.getElementById(id), KEY='mrtd-xss-field-lab-v1';
let state, storageOK=true, view='practice', previewTab='browser', toastTimer;
try{state=restoreState(localStorage.getItem(KEY));}catch{state=initialState();storageOK=false;}
const record=id=>state.records[id]??(state.records[id]=freshRecord());
const current=()=>exercises.find(e=>e.id===state.current)||exercises[0];
const completed=()=>exercises.filter(e=>record(e.id).complete).length;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;document.querySelector('.local-badge').textContent='Storage unavailable · session only';}}
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3200);}
function nav(){
  const ex=current(),mod=modules.find(m=>m.id===ex.module);
  $('breadcrumb').textContent=view==='practice'?mod.name:view==='reference'?'Field reference':'Lab journal';
  $('module-nav').innerHTML=modules.map((m,i)=>{
    const list=exercises.filter(e=>e.module===m.id),done=list.filter(e=>record(e.id).complete).length;
    return `<div class="module-group"><button class="module-button ${ex.module===m.id&&view==='practice'?'active':''}" data-module="${m.id}" ${ex.module===m.id&&view==='practice'?'aria-current="true"':''}><span class="module-symbol" aria-hidden="true">${m.icon}</span><span class="module-name">${m.name}</span><span class="module-fraction">${done}/${list.length}</span></button>${ex.module===m.id&&view==='practice'?`<div class="module-exercises">${list.map((e,j)=>`<button class="exercise-link ${ex.id===e.id?'current':''}" data-exercise="${e.id}" ${ex.id===e.id?'aria-current="step"':''}><span class="step-mark">${record(e.id).complete?'✓':'·'}</span><span>${String(j+1).padStart(2,'0')} ${esc(e.title)}</span></button>`).join('')}</div>`:''}</div>`;
  }).join('');
  $('side-count').textContent=`${completed()} / ${exercises.length}`;
  $('side-progress').style.width=`${completed()/exercises.length*100}%`;
  document.querySelectorAll('[data-view]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.view===view));b.tabIndex=b.dataset.view===view?0:-1;});
  $('content').setAttribute('aria-labelledby',`tab-${view}`);
}
function render(){nav();if(view==='reference')renderReference();else if(view==='journal')renderJournal();else renderPractice();}
function changeExercise(id){if(!exercises.some(e=>e.id===id))return;state.current=id;view='practice';previewTab='browser';save();render();}
function inputHTML(ex,r){
  if(ex.kind==='choice')return `<fieldset style="border:0;margin:0;padding:0"><legend class="input-label">Your prediction <span>SELECT ONE</span></legend><div class="choice-list">${ex.choices.map(([value,label])=>`<label class="choice"><input type="radio" name="answer" value="${esc(value)}" ${r.input===value?'checked':''}><span>${esc(label)}</span></label>`).join('')}</div></fieldset>`;
  if(ex.fields)return ex.fields.map(f=>`<div class="select-field"><label for="field-${f.key}">${esc(f.label)}</label><select id="field-${f.key}" data-field="${f.key}"><option value="">Select…</option>${f.options.map(v=>`<option value="${esc(v)}" ${r.selections[f.key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div>`).join('');
  return `<label class="input-label" for="payload">${esc(ex.label)}<span>INERT INPUT · MAX 4,000 CHARACTERS</span></label><textarea id="payload" class="payload-input" rows="3" maxlength="4000" spellcheck="false" placeholder="${esc(ex.placeholder||'Enter your answer…')}">${esc(r.input)}</textarea><p class="input-help">${ex.kind==='stored'?'Saved comments stay in this browser. A reader visit is a separate step.':'Your input is processed by the teaching model. It never runs as JavaScript.'}</p>`;
}
function renderPractice(){
  const ex=current(),r=record(ex.id),m=modules.find(v=>v.id===ex.module),list=exercises.filter(e=>e.module===ex.module),index=exercises.indexOf(ex),moduleIndex=modules.indexOf(m);
  let result=r.result;
  if(!result&&r.complete)result=evaluate(ex,ex.fields?r.selections:r.input,ex.kind==='stored'?'visit':'run',r.saved);
  const ready={rendered:'Your output will appear here.\nRun the exercise to trace the data.',proof:false,trace:['SOURCE: waiting for input','TRANSFORM: not run','SINK: not reached']};
  $('content').innerHTML=`${!storageOK?'<div class="save-warning">Browser storage is unavailable. You can practice, but progress will last only for this session.</div>':''}${completed()===exercises.length?'<div class="completion-banner"><span class="trophy">✧</span><div><strong>Every boundary explored.</strong><p>You completed all 20 exercises. Revisit any context or review your lab journal.</p></div></div>':''}
    <div class="module-heading"><div><span class="module-number">MODULE ${String(moduleIndex+1).padStart(2,'0')} / 08</span><h2>${esc(m.name)}</h2><p>${esc(m.subtitle)}. Small experiments, clear observations.</p></div><div class="module-meta"><span class="level">${esc(m.level)}</span><span>${list.filter(e=>record(e.id).complete).length} OF ${list.length} COMPLETE</span></div></div>
    <div class="exercise-strip" aria-label="Exercises in this module">${list.map((e,i)=>`<button class="strip-button ${e.id===ex.id?'active':''}" data-exercise="${e.id}" ${e.id===ex.id?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span><span>${esc(e.title)}</span>${record(e.id).complete?'<span class="completed-dot">✓</span>':''}</button>`).join('')}</div>
    <div class="lab-grid"><section class="panel"><div class="panel-header"><span class="step-num">${String(index+1).padStart(2,'0')}</span> EXERCISE BRIEFING <span class="time">◷ ${ex.minutes} min</span></div><div class="panel-body"><h3 class="exercise-title">${esc(ex.title)}</h3><p class="goal">${esc(ex.goal)}</p><p class="concept">${esc(ex.lesson)}</p><div class="code-label"><span>INSPECT THE FLOW</span><span class="context-chip">${esc(ex.context)}</span></div><div class="code-window"><div class="code-dots"><i></i><i></i><i></i></div><pre>${ex.code.split('\n').map((line,i)=>`<span class="line-numbers">${i+1}</span>${esc(line)}`).join('\n')}</pre></div><form id="exercise-form">${inputHTML(ex,r)}<div class="action-row"><button type="submit" class="primary">${ex.kind==='stored'?'Save comment':ex.kind==='choice'||ex.fields?'Check prediction':'Run simulation'} <span>${ex.kind==='stored'?'↓':'→'}</span></button>${ex.kind==='stored'?`<button type="button" id="visit-reader" class="secondary" ${r.saved?'':'disabled'}>Visit as reader ↗</button>`:''}<button type="button" id="hint" class="hint-button">♧ Hint <span class="hint-count">${Math.min(r.hints,ex.hints.length)}/${ex.hints.length}</span></button><button type="button" id="reset-exercise" class="reset-exercise">↺ Reset</button></div></form>${r.hints?`<div class="hints" aria-label="Revealed hints">${ex.hints.slice(0,r.hints).map((h,i)=>`<p><strong>HINT ${i+1}</strong>${esc(h)}</p>`).join('')}</div>`:''}</div></section>
    <div><section class="panel preview-panel"><div class="panel-header"><span>◉</span> SANDBOX OBSERVATION <span class="time">SCRIPTS DISABLED</span></div><div class="preview-tabs" role="tablist" aria-label="Observation view"><button id="browser-tab" type="button" role="tab" aria-selected="${previewTab==='browser'}" class="${previewTab==='browser'?'active':''}">Browser preview</button><button id="trace-tab" type="button" role="tab" aria-selected="${previewTab==='trace'}" class="${previewTab==='trace'?'active':''}">Data-flow trace</button></div><div id="preview-output" role="tabpanel" aria-labelledby="${previewTab==='browser'?'browser-tab':'trace-tab'}"></div><div class="preview-footer"><span class="status-dot"></span> Opaque sandbox · No scripts · No network access</div></section>
    <div id="feedback" aria-live="polite">${result?`<div class="result-card ${result.pass?'success':result.status==='Saved locally'?'':'retry'}"><span class="result-icon">${result.pass?'✓':'⌕'}</span><div><h3>${esc(result.status)}</h3><p>${esc(result.detail)}</p></div></div>`:'<div class="result-card"><span class="result-icon">⌁</span><div><h3>Ready for your first observation</h3><p>Read the flow, make a prediction, then run the model. Hints are here when you need them.</p></div></div>'}</div>
    ${r.complete?`<section class="debrief"><div class="eyebrow">✓ COMPLETED · EXPLANATION</div><h3>What this evidence tells you</h3><p>${esc(ex.explanation)}</p><div class="fix-box"><strong>THE REPAIR</strong>${esc(ex.fix)}</div><button class="primary next-button" id="next-exercise">${index<exercises.length-1?'Continue to the next exercise':'Review your lab journal'} <span>→</span></button></section>`:''}
    <aside class="learning-note"><strong>RESEARCHER'S NOTE</strong>Reflection, HTML injection and script execution are different observations. Describe only what your evidence shows. This lab uses deterministic simulations, not a general-purpose XSS detector.</aside></div></div>
    <div class="exercise-footer"><span>EXERCISE ${String(index+1).padStart(2,'0')} / 20 <span aria-hidden="true">·</span> ${r.attempts} ${r.attempts===1?'ATTEMPT':'ATTEMPTS'}</span><button id="open-journal">✎ Add an observation to your journal →</button></div>`;
  renderPreview(result||ready);
  $('exercise-form').addEventListener('submit',e=>{e.preventDefault();run('run');});
  $('payload')?.addEventListener('input',e=>{r.input=e.target.value;save();});
  document.querySelectorAll('input[name=answer]').forEach(el=>el.addEventListener('change',e=>{r.input=e.target.value;save();}));
  document.querySelectorAll('[data-field]').forEach(el=>el.addEventListener('change',e=>{r.selections[el.dataset.field]=e.target.value;save();}));
  $('visit-reader')?.addEventListener('click',()=>run('visit'));
  $('hint').addEventListener('click',()=>{if(r.hints>=ex.hints.length){toast('All hints are already visible.');return;}r.hints++;save();renderPractice();});
  $('reset-exercise').addEventListener('click',()=>{resetExercise(state,ex.id);save();render();toast('Exercise reset, including its saved comment and notes.');});
  $('browser-tab').addEventListener('click',()=>{previewTab='browser';renderPractice();});
  $('trace-tab').addEventListener('click',()=>{previewTab='trace';renderPractice();});
  $('next-exercise')?.addEventListener('click',()=>{if(index<exercises.length-1)changeExercise(exercises[index+1].id);else{view='journal';render();}});
  $('open-journal').addEventListener('click',()=>{view='journal';render();setTimeout(()=>$(`note-${ex.id}`)?.focus(),0);});
}
function renderPreview(result){
  const root=$('preview-output');
  if(previewTab==='trace'){root.innerHTML='<div class="trace-body"><pre id="trace-text"></pre></div>';$('trace-text').textContent=(result.trace||[]).join('\n\n');return;}
  root.innerHTML='<div class="browser-toolbar"><div class="browser-dots"><i></i><i></i><i></i></div><div class="address-bar">▣ <span>simulation.local</span> / isolated-output</div><span class="sandbox-tag">SANDBOX</span></div>';
  const frame=document.createElement('iframe');frame.className='preview-iframe';frame.title='Isolated harmless simulation output';frame.setAttribute('sandbox','');frame.setAttribute('referrerpolicy','no-referrer');frame.srcdoc=frameDocument(result);root.appendChild(frame);
}
function run(phase){
  const ex=current(),r=record(ex.id),input=ex.fields?r.selections:r.input;
  if(ex.fields?ex.fields.some(f=>!r.selections[f.key]):!r.input.trim()&&!(ex.kind==='stored'&&phase==='visit')){toast('Add an answer before running the model.');return;}
  if(ex.kind==='stored'&&phase!=='visit')r.saved=r.input;
  r.attempts++;r.result=evaluate(ex,input,phase,r.saved);if(r.result.pass)r.complete=true;
  save();render();if(r.result.pass)toast('Exercise complete. Read the explanation and the repair.');
}
function renderReference(){
  $('content').innerHTML=`<section class="reference-header"><h2>A field guide to the boundaries.</h2><p>Keep the data flow in view. Match each defense to the parser and the feature.</p></section><div class="reference-grid">
  <article class="reference-card"><h3>Three questions before a claim</h3><p><b>Can I control the source?</b> Trace a unique marker from its entry point.<br><b>Which parser sees it?</b> Identify text, attribute, URL, script or DOM interpretation.<br><b>What actually happened?</b> Separate reflection, structure change and independently demonstrated execution.</p></article>
  <article class="reference-card"><h3>Delivery and processing can overlap</h3><p><b>Reflected:</b> input returns through the current response.<br><b>Stored:</b> saved input returns in a later read.<br><b>DOM-based:</b> browser code carries untrusted input to a dangerous interpreting sink. A stored value can also take a DOM-based path.</p></article>
  <article class="reference-card wide"><h3>Choose a defense for the context</h3><table class="reference-table"><thead><tr><th>CONTEXT</th><th>PREFERRED APPROACH</th><th>COMMON MISTAKE</th></tr></thead><tbody><tr><td>HTML text</td><td><code>textContent</code> or template auto-escaping</td><td>Interpolate raw input into HTML</td></tr><tr><td>Quoted text attribute</td><td>Set a safe property; encode attribute delimiters when templating</td><td>Escape &lt; but leave the quote delimiter</td></tr><tr><td>URL attribute</td><td>Parse and validate the scheme/destination; assign safely or attribute-encode</td><td>Assume entity encoding validates a scheme</td></tr><tr><td>JavaScript source</td><td>Move data out of executable code; use trusted serialization if embedding is necessary</td><td>Apply an HTML encoder to a JavaScript context</td></tr><tr><td>Intentional rich HTML</td><td>A maintained HTML sanitizer with an explicit policy</td><td>Use a regex blacklist or mutate sanitized HTML unsafely</td></tr><tr><td>CSS</td><td>Keep property names fixed and strictly validate allowed values</td><td>Insert arbitrary input into a style block</td></tr></tbody></table></article>
  <article class="reference-card"><h3>Sources, transforms and sinks</h3><p><b>Sources:</b> query parameters, fragments, stored records, messages and third-party data.<br><b>Transforms:</b> decoding, concatenation, filtering and sanitizing. Track their order.<br><b>Parsing sinks:</b> <code>innerHTML</code>, <code>document.write</code>, raw templates and dynamic code construction. Reachability and context matter.</p><p>A source or sink alone is not a complete finding.</p></article>
  <article class="reference-card"><h3>CSP: another layer of defense</h3><p><code>script-src 'self'</code> does not itself authorize inline blocks. A matching nonce can authorize a script element; it does not authorize inline event handlers. Nonces must be unpredictable and fresh for each response.</p><p>Report-only observes without blocking. Review every enforced policy, the effective directives and browser console violations. Keep safe output handling in place.</p></article>
  <article class="reference-card"><h3>A useful debugging loop</h3><p>1. Place a unique, harmless marker.<br>2. Inspect the raw response and the current DOM.<br>3. Set a DOM mutation breakpoint on the affected node.<br>4. Follow the call stack and transformed value.<br>5. Capture the exact source → transform → sink path.<br>6. Repair the boundary and repeat the same test.</p></article>
  <article class="reference-card"><h3>What this lab models</h3><p>Only fixed exercise flows and the inert MRTD mark element. It does not evaluate general HTML, JavaScript, sanitizers or every CSP directive. A correct lab answer is evidence of learning, not a vulnerability assessment of any website.</p><p>Progress, synthetic comments and journal notes stay in your browser. The hosted site requires your owner account to access it.</p></article>
  <article class="reference-card wide"><h3>Primary references</h3><p>Continue with the authoritative guidance behind these lessons. Links open only when you choose them.</p><div class="source-links"><a href="https://cheatsheetseries.owasp.org/cheatsheets/Cross_Site_Scripting_Prevention_Cheat_Sheet.html" target="_blank" rel="noopener noreferrer">OWASP · XSS Prevention ↗</a><a href="https://cheatsheetseries.owasp.org/cheatsheets/DOM_based_XSS_Prevention_Cheat_Sheet.html" target="_blank" rel="noopener noreferrer">OWASP · DOM-based XSS ↗</a><a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Content-Security-Policy/script-src" target="_blank" rel="noopener noreferrer">MDN · CSP script-src ↗</a><a href="https://developer.mozilla.org/en-US/docs/Web/HTML/Reference/Elements/iframe" target="_blank" rel="noopener noreferrer">MDN · iframe sandbox ↗</a></div></article></div>`;
}
function renderJournal(){
  $('content').innerHTML=`<section class="journal-header"><h2>Make the observation precise.</h2><p>Your private field notes. Capture the source, transforms, sink, observed behavior and repair.</p><div class="journal-summary"><span>${completed()} / 20 EXERCISES COMPLETE</span><span>${exercises.reduce((n,e)=>n+record(e.id).attempts,0)} TOTAL ATTEMPTS</span><button type="button" class="text-button journal-reset" data-reset-all>↺ Reset all progress</button></div></section>${!storageOK?'<div class="save-warning">Storage is unavailable. These notes last only for this session.</div>':''}<div class="journal-grid">${exercises.map((ex,i)=>{const r=record(ex.id);return `<article class="journal-card"><div class="note-top"><h3>${String(i+1).padStart(2,'0')} · ${esc(ex.title)}</h3><span>${r.complete?'✓ COMPLETE':'TO EXPLORE'}</span></div><label class="input-label" for="note-${ex.id}">Evidence & observations</label><textarea id="note-${ex.id}" data-note="${ex.id}" maxlength="2000" placeholder="Source → transform → sink. What did you observe? What does it prove?">${esc(r.note)}</textarea><small>Autosaved on this device · maximum 2,000 characters</small><button data-exercise="${ex.id}">Return to exercise →</button></article>`;}).join('')}</div>`;
  document.querySelectorAll('[data-note]').forEach(el=>el.addEventListener('input',()=>{record(el.dataset.note).note=el.value;save();}));
}
$('module-nav').addEventListener('click',e=>{const b=e.target.closest('[data-module]');if(b){const list=exercises.filter(x=>x.module===b.dataset.module);changeExercise((list.find(x=>!record(x.id).complete)||list[0]).id);}const x=e.target.closest('[data-exercise]');if(x)changeExercise(x.dataset.exercise);});
$('content').addEventListener('click',e=>{if(e.target.closest('[data-reset-all]'))$('reset-dialog').showModal();const b=e.target.closest('[data-exercise]');if(b)changeExercise(b.dataset.exercise);});
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;render();}));
document.querySelector('.page-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const tabs=[...document.querySelectorAll('[data-view]')],idx=tabs.indexOf(document.activeElement);if(idx<0)return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(idx+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;view=tabs[next].dataset.view;render();tabs[next].focus();});
$('isolation-info').addEventListener('click',()=>$('info-dialog').showModal());
$('close-info').addEventListener('click',()=>$('info-dialog').close());$('info-done').addEventListener('click',()=>$('info-dialog').close());
$('reset-all').addEventListener('click',()=>$('reset-dialog').showModal());$('cancel-reset').addEventListener('click',()=>$('reset-dialog').close());
$('confirm-reset').addEventListener('click',()=>{state=initialState();save();view='practice';previewTab='browser';$('reset-dialog').close();render();toast('Your lab is reset. Start with a fresh marker.');});
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();view='practice';render();});
render();
